/**
 * Leviathan Ink live book — single file + Meta publish.
 * Render env: META_APP_ID, META_APP_SECRET
 * Optional: META_REDIRECT (default https://HOST/api/meta/callback)
 */
const http = require("http");
const https = require("https");
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const PORT = Number(process.env.PORT) || 8787;
const SHOP_KEY = process.env.SHOP_KEY || "leviathan-floor";
const DATA = process.env.DATA_FILE || path.join(__dirname, "data", "book.json");
const UP = process.env.UPLOAD_DIR || path.join(__dirname, "data", "uploads");
const META_APP_ID = process.env.META_APP_ID || "";
const META_APP_SECRET = process.env.META_APP_SECRET || "";

const APP_HTML = Buffer.from("", "base64").toString("utf8");

const empty = () => ({
  cfg: null,
  bookings: [],
  messages: [],
  payroll: [],
  accounts: [],
  meta: null,
  updatedAt: 0
});

function load() {
  try {
    return Object.assign(empty(), JSON.parse(fs.readFileSync(DATA, "utf8")));
  } catch (e) {
    return empty();
  }
}
function persist(state) {
  try {
    fs.mkdirSync(path.dirname(DATA), { recursive: true });
    fs.writeFileSync(DATA + ".tmp", JSON.stringify(state));
    fs.renameSync(DATA + ".tmp", DATA);
  } catch (e) {
    console.error("persist failed", e.message);
  }
}
let state = load();

function send(res, code, body, headers) {
  const data = typeof body === "string" ? body : JSON.stringify(body);
  res.writeHead(code, Object.assign({
    "Content-Type": typeof body === "string" ? "text/plain; charset=utf-8" : "application/json; charset=utf-8",
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "Content-Type, X-Shop-Key",
    "Access-Control-Allow-Methods": "GET, PUT, POST, OPTIONS"
  }, headers || {}));
  res.end(data);
}
function keyOk(req) {
  const k = req.headers["x-shop-key"];
  if (!SHOP_KEY) return true;
  return !k || k === SHOP_KEY;
}
function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let n = 0;
    req.on("data", c => {
      n += c.length;
      if (n > 25 * 1024 * 1024) { reject(new Error("too large")); req.destroy(); return; }
      chunks.push(c);
    });
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}
function originFrom(req) {
  const proto = (req.headers["x-forwarded-proto"] || "https").split(",")[0].trim();
  const host = req.headers["x-forwarded-host"] || req.headers.host;
  return proto + "://" + host;
}
function redirectUri(req) {
  return process.env.META_REDIRECT || (originFrom(req) + "/api/meta/callback");
}
function httpsJson(url, method, body) {
  return new Promise((resolve, reject) => {
    const u = new URL(url);
    const payload = body == null ? null : (typeof body === "string" ? body : JSON.stringify(body));
    const opts = {
      hostname: u.hostname,
      path: u.pathname + u.search,
      method: method || "GET",
      headers: { "Accept": "application/json" }
    };
    if (payload) {
      opts.headers["Content-Type"] = "application/x-www-form-urlencoded";
      opts.headers["Content-Length"] = Buffer.byteLength(payload);
    }
    const req = https.request(opts, res => {
      let d = "";
      res.on("data", c => d += c);
      res.on("end", () => {
        try { resolve({ status: res.statusCode, json: JSON.parse(d || "{}"), raw: d }); }
        catch (e) { resolve({ status: res.statusCode, json: {}, raw: d }); }
      });
    });
    req.on("error", reject);
    if (payload) req.write(payload);
    req.end();
  });
}
function graph(pathAndQuery, method, form) {
  const url = pathAndQuery.startsWith("http") ? pathAndQuery : ("https://graph.facebook.com/v21.0/" + pathAndQuery);
  return httpsJson(url, method, form);
}

function saveUpload(dataUrl) {
  fs.mkdirSync(UP, { recursive: true });
  const m = String(dataUrl || "").match(/^data:(image\/[a-zA-Z0-9.+-]+);base64,(.+)$/);
  if (!m) throw new Error("Photo must be an image");
  const ext = m[1].includes("png") ? "png" : "jpg";
  const id = crypto.randomBytes(8).toString("hex") + "." + ext;
  fs.writeFileSync(path.join(UP, id), Buffer.from(m[2], "base64"));
  return id;
}

const server = http.createServer(async (req, res) => {
  if (req.method === "OPTIONS") return send(res, 204, "");
  const url = new URL(req.url, "http://localhost");
  const p = url.pathname;

  if (p === "/api/health") {
    return send(res, 200, {
      ok: true, shop: "Leviathan Ink",
      bookings: (state.bookings || []).length,
      updatedAt: state.updatedAt,
      meta: !!(state.meta && state.meta.pageToken)
    });
  }

  if (p === "/api/state" && req.method === "GET") {
    if (!keyOk(req)) return send(res, 401, { error: "Bad shop key" });
    return send(res, 200, {
      cfg: state.cfg, bookings: state.bookings || [], messages: state.messages || [],
      payroll: state.payroll || [], accounts: state.accounts || [], updatedAt: state.updatedAt || 0
    });
  }

  if (p === "/api/state" && req.method === "PUT") {
    if (!keyOk(req)) return send(res, 401, { error: "Bad shop key" });
    try {
      const incoming = JSON.parse(await readBody(req));
      state = {
        cfg: incoming.cfg != null ? incoming.cfg : state.cfg,
        bookings: Array.isArray(incoming.bookings) ? incoming.bookings : state.bookings,
        messages: Array.isArray(incoming.messages) ? incoming.messages : state.messages,
        payroll: Array.isArray(incoming.payroll) ? incoming.payroll : state.payroll,
        accounts: Array.isArray(incoming.accounts) ? incoming.accounts : state.accounts,
        meta: state.meta,
        updatedAt: Date.now()
      };
      persist(state);
      return send(res, 200, { ok: true, updatedAt: state.updatedAt });
    } catch (e) {
      return send(res, 400, { error: "Invalid body" });
    }
  }

  if (p.startsWith("/uploads/")) {
    const id = path.basename(p);
    const file = path.join(UP, id);
    if (!file.startsWith(UP) || !fs.existsSync(file)) return send(res, 404, "Not found");
    const buf = fs.readFileSync(file);
    const type = id.endsWith(".png") ? "image/png" : "image/jpeg";
    res.writeHead(200, { "Content-Type": type, "Cache-Control": "public, max-age=86400" });
    return res.end(buf);
  }

  if (p === "/api/meta/status") {
    return send(res, 200, {
      configured: !!(META_APP_ID && META_APP_SECRET),
      connected: !!(state.meta && state.meta.pageToken),
      pageName: state.meta && state.meta.pageName,
      pageId: state.meta && state.meta.pageId,
      igUserId: state.meta && state.meta.igUserId
    });
  }

  if (p === "/api/meta/login") {
    if (!META_APP_ID || !META_APP_SECRET) {
      return send(res, 400, { error: "Set META_APP_ID and META_APP_SECRET on Render first." });
    }
    const redir = redirectUri(req);
    const scope = [
      "pages_show_list",
      "pages_manage_posts",
      "pages_read_engagement",
      "pages_read_user_content",
      "instagram_basic",
      "instagram_content_publish",
      "business_management"
    ].join(",");
    const loc = "https://www.facebook.com/v21.0/dialog/oauth?client_id=" + encodeURIComponent(META_APP_ID) +
      "&redirect_uri=" + encodeURIComponent(redir) +
      "&scope=" + encodeURIComponent(scope) +
      "&response_type=code";
    res.writeHead(302, { Location: loc });
    return res.end();
  }

  if (p === "/api/meta/callback") {
    try {
      const code = url.searchParams.get("code");
      const err = url.searchParams.get("error_description") || url.searchParams.get("error");
      if (err) return send(res, 400, "Facebook said: " + err);
      if (!code) return send(res, 400, "Missing code");
      const redir = redirectUri(req);
      const tok = await graph("oauth/access_token?client_id=" + META_APP_ID +
        "&client_secret=" + META_APP_SECRET +
        "&redirect_uri=" + encodeURIComponent(redir) +
        "&code=" + encodeURIComponent(code));
      const userToken = tok.json.access_token;
      if (!userToken) return send(res, 400, "No user token: " + (tok.raw || ""));
      const longT = await graph("oauth/access_token?grant_type=fb_exchange_token&client_id=" + META_APP_ID +
        "&client_secret=" + META_APP_SECRET +
        "&fb_exchange_token=" + encodeURIComponent(userToken));
      const longUser = (longT.json && longT.json.access_token) || userToken;
      const pages = await graph("me/accounts?fields=id,name,access_token,instagram_business_account&access_token=" + encodeURIComponent(longUser));
      const list = (pages.json && pages.json.data) || [];
      if (!list.length) return send(res, 400, "No Facebook Pages on this account. Use the Page admin login.");
      const want = list.find(x => /leviathan/i.test(x.name || "")) || list[0];
      let igUserId = want.instagram_business_account && want.instagram_business_account.id;
      if (!igUserId) {
        const pg = await graph(want.id + "?fields=instagram_business_account&access_token=" + encodeURIComponent(want.access_token));
        igUserId = pg.json.instagram_business_account && pg.json.instagram_business_account.id;
      }
      state.meta = {
        pageId: want.id,
        pageName: want.name,
        pageToken: want.access_token,
        igUserId: igUserId || "",
        connectedAt: Date.now()
      };
      persist(state);
      res.writeHead(302, { Location: originFrom(req) + "/?meta=connected" });
      return res.end();
    } catch (e) {
      return send(res, 500, "Connect failed: " + e.message);
    }
  }

  if (p === "/api/meta/disconnect" && req.method === "POST") {
    state.meta = null;
    persist(state);
    return send(res, 200, { ok: true });
  }

  if (p === "/api/meta/publish" && req.method === "POST") {
    if (!state.meta || !state.meta.pageToken) {
      return send(res, 400, { error: "Shop Facebook is not connected. Admin → Studio → Connect." });
    }
    try {
      const body = JSON.parse(await readBody(req));
      const caption = String(body.caption || "").slice(0, 2200);
      if (!body.image) return send(res, 400, { error: "Photo required" });
      const id = saveUpload(body.image);
      const publicUrl = originFrom(req) + "/uploads/" + id;
      const out = { facebook: false, instagram: false, message: "", errors: [] };

      if (body.facebook !== false) {
        const fb = await graph(
          state.meta.pageId + "/photos?url=" + encodeURIComponent(publicUrl) +
          "&caption=" + encodeURIComponent(caption) +
          "&access_token=" + encodeURIComponent(state.meta.pageToken),
          "POST"
        );
        if (fb.json && (fb.json.id || fb.json.post_id)) out.facebook = true;
        else out.errors.push("Facebook: " + (fb.json.error && fb.json.error.message || fb.raw));
      }

      if (body.instagram !== false && state.meta.igUserId) {
        const con = await graph(
          state.meta.igUserId + "/media?image_url=" + encodeURIComponent(publicUrl) +
          "&caption=" + encodeURIComponent(caption) +
          "&access_token=" + encodeURIComponent(state.meta.pageToken),
          "POST"
        );
        const creation = con.json && con.json.id;
        if (!creation) {
          out.errors.push("Instagram container: " + (con.json.error && con.json.error.message || con.raw));
        } else {
          const pub = await graph(
            state.meta.igUserId + "/media_publish?creation_id=" + encodeURIComponent(creation) +
            "&access_token=" + encodeURIComponent(state.meta.pageToken),
            "POST"
          );
          if (pub.json && pub.json.id) out.instagram = true;
          else out.errors.push("Instagram publish: " + (pub.json.error && pub.json.error.message || pub.raw));
        }
      } else if (body.instagram !== false && !state.meta.igUserId) {
        out.errors.push("Instagram is not linked to the Facebook Page.");
      }

      if (out.facebook || out.instagram) {
        out.message = "Posted to the shop account(s).";
        return send(res, 200, out);
      }
      return send(res, 400, { error: out.errors.join(" | ") || "Publish failed" });
    } catch (e) {
      return send(res, 500, { error: e.message });
    }
  }

  if (p === "/" || p === "/index.html" || p === "/app") {
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" });
    return res.end(APP_HTML);
  }
  return send(res, 404, "Not found");
});

server.listen(PORT, "0.0.0.0", () => {
  console.log("Leviathan live book on " + PORT);
});
